var EXTRA=[{dot:"gray",j:"Asia-Pacific Journal of Sports Medicine, Arthroscopy, Rehabilitation and Technology",h:"Una concavità stabile del menisco che sembra una lesione ma non lo è",v:"Caso clinico: un reperto artroscopico incidentale a valle del menisco mediale mima una separazione meniscocapsulare, ma risulta stabile alla prova dinamica e viene lasciato intatto senza conseguenze a due anni.",pmid:'42733659',doi:'10.1016/j.asmart.2026.06.003',temi:["menisco","artroscopia","diagnosi differenziale"]},{dot:"gray",j:"Arthroscopy",h:"Perché la misura dell'altezza rotulea resta decisiva nella stabilizzazione",v:"Commento editoriale: l'indice di Caton-Deschamps resta lo strumento pratico più affidabile per misurare la patella alta prima e dopo la distalizzazione della tuberosità tibiale.",pmid:'42732546',doi:'10.1002/arj.70593',temi:["mpfl","instabilità rotulea","imaging"]},{dot:"gray",j:"Arthroscopy",h:"Riparare il menisco insieme al crociato posteriore conviene, come per l'anteriore",v:"Commento editoriale: la riparazione meniscale eseguita insieme alla ricostruzione del legamento crociato posteriore mostra risultati migliori della riparazione isolata, come già noto per il crociato anteriore.",pmid:'42732545',doi:'10.1002/arj.70595',temi:["menisco","lcp","tecnica chirurgica"]},{dot:"gray",j:"Biomechanics and Modeling in Mechanobiology",h:"Nel trapianto osteocondrale rotuleo conta anche lo spessore della cartilagine",v:"Modello computazionale: la mancata corrispondenza di spessore fra cartilagine del donatore e del ricevente concentra la deformazione all'interfaccia del trapianto osteocondrale della rotula, oltre alla sola congruenza di superficie.",pmid:'42730942',doi:'10.1007/s10237-026-02128-9',temi:["cartilagine","allograft osteocondrale","biomeccanica computazionale"]},{dot:"gray",j:"Drug Design, Development and Therapy",h:"Un blocco anestetico a iniezione singola può bastare dopo la protesi di ginocchio",v:"Trial randomizzato: una singola iniezione di bupivacaina liposomiale non è inferiore al catetere continuo per il dolore posteriore dopo protesi totale di ginocchio, anche se il catetere resta migliore su consumo di oppioidi e riabilitazione precoce.",pmid:'42730321',doi:'10.2147/DDDT.S626404',temi:["protesi totale","anestesia regionale","gestione del dolore"]},{dot:"gray",j:"SICOT-J",h:"Il sonno peggiora dopo la protesi, e la melatonina non lo risolve del tutto",v:"Trial randomizzato su protesi d'anca e di ginocchio: il sonno peggiora prima e dopo l'intervento, recupera più in fretta dopo la protesi di ginocchio che dopo quella d'anca, e la melatonina perioperatoria non ne migliora la qualità in modo consistente.",pmid:'42735358',doi:'10.1051/sicotj/2026029',temi:["protesi totale","recupero post-operatorio","sonno"]},{dot:"gray",j:"Computational Biology and Chemistry",h:"Un modello di intelligenza artificiale classifica l'osteoporosi dalla radiografia del ginocchio",v:"Un framework di deep learning combina localizzazione automatica dell'area tibiofemorale e classificazione per riconoscere osteopenia e osteoporosi da semplici radiografie di ginocchio, ancora in fase di ricerca.",pmid:'42731440',doi:'10.1016/j.compbiolchem.2026.109399',temi:["intelligenza artificiale","osteoporosi","imaging"]},{dot:"gray",j:"Frontiers in Surgery",h:"Quando la protesi robotica scopre in sala un difetto osseo, il robot corregge anche quello",v:"Caso clinico: durante una protesi totale robot-assistita, un conflitto meccanico inatteso ha portato a convertire l'intervento in un'osteotomia femorale correttiva guidata dallo stesso sistema robotico, con buon risultato precoce in un singolo paziente.",pmid:'42729879',doi:'10.3389/fsurg.2026.1910960',temi:["protesi robotica","osteotomia","caso clinico"]},{dot:"gray",j:"Journal of Diabetes and Metabolic Disorders",h:"I farmaci per l'artrosi del ginocchio non peggiorano il diabete",v:"Studio retrospettivo: nei pazienti con artrosi di ginocchio e diabete di tipo 2, l'uso prolungato di glucosamina o diacereina non modifica in modo rilevante il controllo glicemico rispetto a chi non li usa.",pmid:'42732213',doi:'10.1007/s40200-026-02069-1',temi:["gonartrosi","diabete","farmacologia"]},{dot:"gray",j:"Arthroplasty Today",h:"Chirurghi e pazienti concordano sulle priorità per la protesi in caso di obesità",v:"Un gruppo di lavoro misto di chirurghi e pazienti indica come priorità comuni l'ottimizzazione preoperatoria, la formazione dei chirurghi e la decisione condivisa, per l'assistenza alla protesi di anca e ginocchio nei pazienti con indice di massa corporea elevato.",pmid:'42699140',doi:'10.1016/j.artd.2026.102127',temi:["protesi totale","obesità","consensus"]}];
var SCOPERTE=[{t:"Una capsula di medicina tradizionale cinese, testata con un trial randomizzato, per l'artrosi di ginocchio",v:"Centoventi pazienti, dodici settimane, in doppio cieco contro placebo: aggiungere le capsule Jintiange — una formula sintetica ispirata all'osso di tigre, usata nella medicina tradizionale cinese — al celecoxib migliora dolore e funzione più del solo farmaco antinfiammatorio. Un ponte concreto, testato con gli strumenti della medicina occidentale, fra due mondi che raramente si parlano: da leggere con la cautela dovuta a un singolo trial monocentrico, non come una conferma definitiva.",pmid:'42733221',doi:'10.12659/MSM.951501',temi:["medicina tradizionale cinese","gonartrosi","farmacologia"]},{t:"Una nanoparticella camuffata da cellula della cartilagine per fermare l'artrosi dall'interno",v:"In laboratorio, un nanosistema costruito con DNA a forma di tetraedro, avvolto in una membrana di condrociti veri, consegna un antiossidante naturale direttamente alle cellule della cartilagine infiammate, ripristinando l'equilibrio energetico e frenando l'invecchiamento cellulare. Bioingegneria allo stadio più precoce — cellule in laboratorio, non pazienti — ma con una direzione precisa: usare il camuffamento biologico per portare farmaci esattamente dove servono, dentro l'articolazione.",pmid:'42733614',doi:'10.1016/j.mtbio.2026.103609',temi:["bioingegneria","nanomedicina","cartilagine"]},{t:"Un'intelligenza artificiale leggera legge la risonanza del ginocchio meglio dei modelli pesanti",v:"Un modello di deep learning compatto, 1,1 milioni di parametri contro le decine di milioni dei modelli concorrenti, classifica la gravità dell'artrosi di ginocchio da risonanza magnetica in cinque gradi, con un'accuratezza fra le migliori del settore e un'attenzione dimostrata alle aree davvero rilevanti — cartilagine e spazio articolare. Un segnale di una tendenza di fondo nell'intelligenza artificiale applicata all'imaging: non serve sempre un modello enorme per un buon risultato clinico.",pmid:'42728517',doi:'10.1007/s10278-026-02251-0',temi:["intelligenza artificiale","imaging","gonartrosi"]}];
var SOC={"1":{"video":"Un grande registro svizzero di protesi di ginocchio, oltre 120.000 casi, mostra che chi ha già subito un intervento allo stesso ginocchio in passato — per un legamento, per correggere l'asse della gamba, o per un'infezione — corre un rischio più alto di dover essere rioperato per infezione dopo la protesi totale. Il rischio cresce con il tipo e con il numero di interventi precedenti: più alto dopo una chirurgia per infezione o un'osteotomia, più contenuto dopo una ricostruzione del crociato anteriore, e comunque più marcato oltre i due interventi sullo stesso ginocchio. Non è un dato che sconsigli la protesi a chi ha già operato il ginocchio: è un'informazione che medico curante, fisioterapista e paziente dovrebbero conoscere insieme, perché cambia quanto attentamente sorvegliare la ferita e il decorso postoperatorio."},"2":{"video":"Una revisione di trenta studi scientifici ha messo insieme i dati su un tipo di allenamento specifico — l'allenamento neuromuscolare, fatto di esercizi di equilibrio, salti controllati e rinforzo muscolare — per capire se riduce davvero il rischio di infortunio al ginocchio nello sport. La risposta è sì, e vale sia per gli adulti sia per gli adolescenti, senza una differenza chiara legata all'età. Contano di più le caratteristiche del programma: funzionano meglio i programmi che uniscono più tipi di esercizio insieme e che vengono seguiti in modo standardizzato, con un protocollo preciso, invece che in modo generico. Gli stessi ricercatori dicono che le indicazioni su quanto allenarsi e con quali esercizi esatti sono ancora da confermare: il messaggio di fondo — allenarsi in modo mirato aiuta a prevenire — è però solido e utile da portare a chi pratica sport a rischio."},"3":{"video":"Uno studio ha confrontato, nello stesso paziente, il ginocchio operato di legamento crociato anteriore con il ginocchio sano dell'altra gamba, quasi sei anni dopo l'intervento. Il risultato: il ginocchio operato viene «sentito» un po' di più, cioè meno dimenticato, rispetto a quello sano — anche quando i test clinici sono buoni. La cosa più interessante è che a spiegare questa differenza non è tanto la stabilità misurata dal medico, quanto quanto il paziente si sente psicologicamente pronto e sicuro del proprio ginocchio: chi ha più fiducia tende a percepire meno la differenza fra le due gambe. Lo studio riguarda un solo tipo di innesto e ricostruzioni senza un intervento aggiuntivo di stabilizzazione laterale: un dato interessante sulla percezione del paziente, da leggere come spunto, non come regola valida per ogni tecnica chirurgica."},"4":{"video":"Uno studio di laboratorio ha guardato come si coordinano fra loro i muscoli della gamba, non solo quanto sono forti, durante un salto impegnativo in persone operate al legamento crociato anteriore, confrontate con persone che non si sono mai infortunate. Il risultato: nel ginocchio operato manca uno schema muscolare specifico, che nei ginocchi sani aiuta a stabilizzare lateralmente l'articolazione durante l'atterraggio. In pratica, anche se la forza torna quasi normale, il modo in cui i muscoli lavorano insieme può restare diverso. È uno studio piccolo, di laboratorio, non ancora collegato a un esito clinico concreto come il reinfortunio: indica però una direzione precisa per l'allenamento del rientro allo sport, oltre alla sola misura della forza."},"5":{"video":"Un esperimento di laboratorio su tessuto animale ha confrontato quattro modi di riparare la parte posteriore del menisco, quella più vicina al centro del ginocchio: due modi di cucire il filo di sutura, e due modi di fissarlo all'osso della tibia. Il risultato è che nessuna delle quattro combinazioni si è dimostrata chiaramente migliore delle altre: la resistenza del punto di riparazione è risultata simile in tutti i gruppi. Il punto che cede per primo, sempre, è dove il filo attraversa il tessuto del menisco — non il nodo, non l'ancoraggio nell'osso. È un esperimento con pochi campioni per gruppo, che misura solo la resistenza immediata, prima che il tessuto inizi a guarire: informa su come si comportano meccanicamente queste tecniche, ma non dimostra che siano davvero equivalenti in un paziente reale."}};
var SOCV={"1":{"video":{"chir":["Un registro nazionale svizzero, il Swiss Implant Registry, ha seguito 121.692 protesi totali di ginocchio. Chi aveva già subito un intervento sullo stesso ginocchio — osteotomia tibiale, ricostruzione del legamento crociato anteriore, sinovectomia, chirurgia per infezione — mostra un rischio più alto di revisione, sia per qualunque causa (odds ratio 1,33) sia specificamente per infezione periprotesica (odds ratio 1,22).","Il rischio non è uguale per tutti gli interventi precedenti: la chirurgia per infezione pregressa porta il rischio più alto (odds ratio 3,30), seguita dall'osteotomia tibiale (2,12), dalla sinovectomia (2,18), dall'osteosintesi tibiale (1,71) e dalla ricostruzione del crociato anteriore (1,44). E il rischio di infezione sale in modo netto solo oltre due interventi precedenti sullo stesso ginocchio.","È un dato di registro: niente esame clinico diretto, niente dettaglio sulla tecnica o sull'innesto usati negli interventi precedenti. Ma con oltre centoventimila protesi analizzate, il messaggio pratico regge: la storia chirurgica di quel ginocchio va portata al colloquio preoperatorio come un fattore di rischio quantificabile, non come un dettaglio anagrafico."],"misto":["Un grande registro svizzero di protesi di ginocchio, oltre 120.000 casi, mostra che chi ha già subito un intervento allo stesso ginocchio in passato — per un legamento, per correggere l'asse della gamba, o per un'infezione — corre un rischio più alto di dover essere rioperato per infezione dopo la protesi totale.","Il rischio cresce con il tipo e con il numero di interventi precedenti: più alto dopo una chirurgia per infezione o un'osteotomia, più contenuto dopo una ricostruzione del crociato anteriore, e comunque più marcato oltre i due interventi sullo stesso ginocchio.","Non è un dato che sconsigli la protesi a chi ha già operato il ginocchio: è un'informazione che medico curante, fisioterapista e paziente dovrebbero conoscere insieme, perché cambia quanto attentamente sorvegliare la ferita e il decorso postoperatorio."],"pazienti":["Uno studio su oltre 120.000 protesi di ginocchio in Svizzera ha guardato che cosa succede a chi aveva già subito un intervento allo stesso ginocchio prima della protesi.","Chi aveva già avuto un intervento precedente — per esempio per un legamento o per correggere la gamba storta — ha una probabilità un po' più alta di avere un'infezione dopo la protesi, soprattutto se gli interventi precedenti erano più di due.","Non significa che chi ha già operato il ginocchio non possa fare la protesi con successo: significa solo che vale la pena parlarne con il proprio chirurgo prima dell'intervento, così da sorvegliare con più attenzione la guarigione."]},"linkedin":{"chir":["Swiss Implant Registry, 121.692 protesi totali di ginocchio primarie (2015-2022): la storia chirurgica omolaterale pregressa è un fattore di rischio indipendente per la revisione, procedura-specifico.","Odds ratio per revisione per infezione: chirurgia per infezione pregressa 3,30 (IC 95% 1,56-6,96); osteotomia tibiale 2,12 (1,60-2,82); sinovectomia 2,18 (1,27-3,73); osteosintesi tibiale 1,71 (1,10-2,68); ricostruzione del LCA 1,44 (1,10-1,90). Oltre due interventi precedenti: OR 2,01 (1,51-2,68).","Limiti: dati amministrativi, nessun dettaglio su tecnica/innesto delle procedure precedenti, possibile confondimento per indicazione. Nella stratificazione del rischio preoperatorio della protesi totale, la storia chirurgica del ginocchio merita un posto quantificato, non solo intuitivo."],"misto":["Un registro nazionale su oltre 120.000 protesi di ginocchio mostra che chi era già stato operato allo stesso ginocchio in passato ha un rischio più alto di revisione per infezione dopo la protesi totale.","Il rischio varia per tipo di intervento precedente ed è più marcato con più di due interventi sullo stesso ginocchio: un'informazione utile per medico curante, fisioterapista e paziente nel preparare l'intervento e nel sorvegliare il decorso.","È un dato di registro, non uno studio sperimentale: non cambia l'indicazione alla protesi, ma arricchisce il colloquio informativo prima dell'intervento."],"pazienti":["Uno studio su oltre 120.000 protesi di ginocchio in Svizzera ha guardato chi aveva già avuto un intervento sullo stesso ginocchio prima della protesi totale.","Chi aveva già subito un intervento — per esempio un legamento o una correzione dell'asse della gamba — ha una probabilità leggermente più alta di infezione dopo la protesi, soprattutto con più di due interventi precedenti.","Vale la pena parlarne con il chirurgo prima dell'intervento: non è un motivo per rinunciare alla protesi, ma un elemento in più da conoscere insieme."]},"instagram":{"chir":["Registro svizzero, 121.692 protesi di ginocchio: la storia chirurgica pregressa dello stesso ginocchio pesa sul rischio di revisione per infezione — OR da 1,44 (LCA) a 3,30 (chirurgia per infezione pregressa).","Oltre due interventi precedenti: OR 2,01 per infezione. Dato di registro, nessun dettaglio su tecnica/innesto: un elemento in più nella stratificazione preoperatoria, non una controindicazione.","Fonte: Knee Surgery, Sports Traumatology, Arthroscopy, settembre 2026 — link a PubMed nella scheda dell'app."],"misto":["Un ginocchio già operato in passato conta nel rischio di infezione dopo la protesi totale — lo mostra un registro svizzero su oltre 120.000 casi.","Il rischio cresce con il numero di interventi precedenti: un'informazione da portare al colloquio prima della protesi, non un motivo per rinunciarvi.","Ne parliamo con chi segue la riabilitazione: fisioterapisti e medici curanti trovano il dettaglio nella scheda estesa dell'app."],"pazienti":["Chi ha già operato lo stesso ginocchio in passato ha un rischio un po' più alto di infezione dopo la protesi totale, mostra uno studio svizzero su oltre 120.000 casi.","Non è un motivo per non fare la protesi: è un'informazione in più da condividere col proprio chirurgo prima dell'intervento.","Se hai già avuto un intervento a quel ginocchio, portalo al colloquio pre-operatorio: fa parte del quadro completo."]},"reel":{"chir":["[Registro svizzero · 121.692 protesi di ginocchio] Chi era già stato operato allo stesso ginocchio rischia di più la revisione per infezione dopo la protesi totale.","[OR da 1,44 a 3,30 secondo il tipo di intervento precedente] Il rischio più alto: chi aveva già avuto un intervento per infezione. Oltre due interventi precedenti, il rischio sale ancora.","[Dato di registro, non uno studio sperimentale] La storia chirurgica del ginocchio va portata al colloquio prima della protesi — non è un divieto, è un'informazione in più."],"misto":["[121.692 protesi di ginocchio, registro svizzero] Un ginocchio già operato in passato pesa sul rischio di infezione dopo la protesi.","[Più interventi precedenti, più rischio] Osteotomia, legamento crociato, infezione pregressa: ognuno pesa in modo diverso.","[Un'informazione per il colloquio pre-intervento] Non cambia la decisione di operare, arricchisce come prepararsi."],"pazienti":["[Se hai già operato quel ginocchio] Uno studio su 120.000 protesi mostra un rischio un po' più alto di infezione dopo la protesi totale.","[Più interventi prima, più attenzione dopo] Il rischio cresce soprattutto oltre due interventi sullo stesso ginocchio.","[Parlane col tuo chirurgo] Non è un ostacolo alla protesi: è un elemento in più da conoscere insieme."]}},"2":{"video":{"chir":["Una revisione sistematica e meta-analisi di 30 studi, registrata su PROSPERO, ha valutato l'efficacia dell'allenamento neuromuscolare — esercizi di stabilizzazione all'atterraggio, pliometria, rinforzo del core e degli arti inferiori — nel prevenire gli infortuni al ginocchio nello sport. Il risultato: riduzione significativa del rischio, con un effect estimate di 0,670 e intervallo di confidenza al 95% fra 0,547 e 0,820.","L'effetto protettivo compare sia sopra i 18 anni sia a 18 anni o meno, senza una differenza statisticamente significativa fra i due gruppi: la meta-regressione non trova un ruolo dell'età media né della proporzione di atlete donne. Contano invece la struttura del programma: multicomponente, con almeno tre elementi diversi, e standardizzato, cioè applicato secondo un protocollo fisso.","Gli stessi autori avvertono che le analisi su dose — quindici-venti minuti a seduta, due-tre sedute a settimana, oltre venticinque settimane — e su singole componenti sono esplorative, non confermatorie. La direzione del beneficio è solida; i dettagli del programma ideale restano da affinare con altri studi."],"misto":["Una revisione di trenta studi scientifici ha messo insieme i dati su un tipo di allenamento specifico — l'allenamento neuromuscolare, fatto di esercizi di equilibrio, salti controllati e rinforzo muscolare — per capire se riduce davvero il rischio di infortunio al ginocchio nello sport.","La risposta è sì, e vale sia per gli adulti sia per gli adolescenti, senza una differenza chiara legata all'età. Contano di più le caratteristiche del programma: funzionano meglio i programmi che uniscono più tipi di esercizio insieme e che vengono seguiti in modo standardizzato, con un protocollo preciso, invece che in modo generico.","Gli stessi ricercatori dicono che le indicazioni su quanto allenarsi e con quali esercizi esatti sono ancora da confermare: il messaggio di fondo — allenarsi in modo mirato aiuta a prevenire — è però solido e utile da portare a chi pratica sport a rischio."],"pazienti":["Una grande revisione di studi scientifici ha guardato se allenarsi in un certo modo — con esercizi di equilibrio, salti controllati, rinforzo dei muscoli della gamba — aiuta davvero a prevenire gli infortuni al ginocchio nello sport.","La risposta è sì, sia per i ragazzi sia per gli adulti: chi segue questi programmi si infortunia meno al ginocchio rispetto a chi non li segue. Funzionano meglio i programmi completi, con più tipi di esercizio insieme, seguiti con costanza per diversi mesi.","È una buona notizia soprattutto per genitori di ragazzi sportivi e per chi pratica sport con cambi di direzione frequenti: prevenire con l'allenamento giusto ha un fondamento scientifico solido, anche se i dettagli esatti del programma migliore sono ancora in discussione."]},"linkedin":{"chir":["Revisione sistematica e meta-analisi, 30 studi (RCT e non randomizzati), PROSPERO CRD420261327352: l'allenamento neuromuscolare (NMT) riduce il rischio di infortunio al ginocchio nello sport (effect estimate 0,670; IC 95% 0,547-0,820; p<0,001; I²=58,5%).","Effetto protettivo sia sopra sia sotto i 18 anni, senza differenza significativa fra sottogruppi. Programmi multicomponente (≥3 elementi): effect estimate 0,643 (vs non significativo con <3 componenti, p=0,045 fra sottogruppi). Programmi standardizzati: 0,592 (vs non significativo se non standardizzati).","Limiti dichiarati dagli autori: analisi su dose e componenti esplorative, non confermatorie; disegni eterogenei inclusi insieme. Un argomento solido per programmi di prevenzione strutturati nella popolazione sportiva giovane e adulta."],"misto":["Una meta-analisi di 30 studi conferma che l'allenamento neuromuscolare riduce il rischio di infortunio al ginocchio nello sport, sia negli adulti sia negli adolescenti, senza una differenza netta legata all'età.","Contano la struttura del programma — più componenti insieme — e la standardizzazione: seguito con un protocollo fisso funziona meglio di un allenamento generico.","Le indicazioni esatte su durata e frequenza sono ancora provvisorie, ma la direzione del beneficio è solida: un argomento concreto per chi lavora con giovani sportivi."],"pazienti":["Una revisione di 30 studi mostra che allenarsi con esercizi mirati — equilibrio, salti controllati, rinforzo muscolare — riduce il rischio di infortunio al ginocchio nello sport, sia nei ragazzi sia negli adulti.","Funzionano meglio i programmi completi, seguiti con costanza per diversi mesi.","Un argomento in più per genitori di ragazzi sportivi e per chi pratica sport a rischio di torsione del ginocchio."]},"instagram":{"chir":["Meta-analisi di 30 studi: l'allenamento neuromuscolare riduce il rischio di infortunio al ginocchio nello sport (effect estimate 0,670; IC 95% 0,547-0,820), senza differenza chiara fra atleti maggiorenni e minorenni.","Meglio i programmi multicomponente e standardizzati. Dose e componenti singole restano analisi esplorative — la direzione del beneficio è comunque solida.","Fonte: Frontiers in Public Health, agosto 2026 — protocollo su PROSPERO, link a PubMed nella scheda dell'app."],"misto":["L'allenamento neuromuscolare riduce il rischio di infortunio al ginocchio nello sport, a ogni età — lo conferma una meta-analisi di 30 studi.","Meglio i programmi completi e seguiti con un protocollo fisso, per almeno qualche mese.","Utile per chi lavora con giovani sportivi: preparatori atletici e fisioterapisti trovano il dettaglio nella scheda estesa."],"pazienti":["Allenarsi con esercizi di equilibrio, salti controllati e rinforzo muscolare riduce il rischio di infortunio al ginocchio nello sport, sia nei ragazzi sia negli adulti.","Un buon argomento per chi ha figli sportivi o pratica sport a rischio per il ginocchio.","Parlane con l'allenatore o il fisioterapista per un programma adatto all'età e allo sport praticato."]},"reel":{"chir":["[Meta-analisi di 30 studi] L'allenamento neuromuscolare riduce il rischio di infortunio al ginocchio nello sport.","[Effect estimate 0,670, IC 95% 0,547-0,820] Funziona a ogni età, meglio se multicomponente e standardizzato.","[Dose esatta ancora in discussione] La direzione del beneficio però è solida."],"misto":["[30 studi in meta-analisi] Allenarsi in modo mirato previene gli infortuni al ginocchio nello sport.","[Adulti e adolescenti] Funziona a ogni età, meglio con un programma completo.","[Ancora da affinare] I dettagli del programma ideale, non il beneficio di fondo."],"pazienti":["[Sport e ginocchio] Un allenamento mirato può prevenire l'infortunio, mostra una grande revisione di studi.","[Ragazzi e adulti] Funziona a ogni età, meglio se costante nel tempo.","[Parlane con l'allenatore o il fisioterapista] Per un programma adatto a te."]}},"3":{"video":{"chir":["Uno studio retrospettivo turco ha confrontato, nello stesso paziente, il ginocchio ricostruito con il ginocchio sano controlaterale, a quasi sei anni dalla ricostruzione isolata del legamento crociato anteriore con innesto di hamstring. Il punteggio Forgotten Joint Score-12, che misura quanto un paziente «dimentica» di avere un ginocchio operato, è significativamente più basso nel ginocchio ricostruito: 81,2 contro 90,1, con p inferiore a 0,001.","Il fattore che meglio spiega questa differenza non è la stabilità clinica misurata dal chirurgo, ma la prontezza psicologica del paziente, misurata con la scala ACL-RSI: correla fortemente con il punteggio di consapevolezza articolare (rho 0,786) e ne è predittore indipendente. Un'analisi di mediazione mostra che l'instabilità rotazionale residua influenza la percezione del paziente soprattutto attraverso questa componente psicologica.","Lo studio riguarda solo l'innesto di hamstring, in ricostruzioni isolate senza tenodesi extra-articolare laterale: un limite importante per chi, come te, usa il tendine quadricipitale e associa sistematicamente un rinforzo laterale. Il messaggio di fondo — la componente psicologica pesa quanto la stabilità clinica — resta comunque un'ipotesi di lavoro da verificare sulla propria casistica."],"misto":["Uno studio ha confrontato, nello stesso paziente, il ginocchio operato di legamento crociato anteriore con il ginocchio sano dell'altra gamba, quasi sei anni dopo l'intervento. Il risultato: il ginocchio operato viene «sentito» un po' di più, cioè meno dimenticato, rispetto a quello sano — anche quando i test clinici sono buoni.","La cosa più interessante è che a spiegare questa differenza non è tanto la stabilità misurata dal medico, quanto quanto il paziente si sente psicologicamente pronto e sicuro del proprio ginocchio: chi ha più fiducia tende a percepire meno la differenza fra le due gambe.","Lo studio riguarda un solo tipo di innesto e ricostruzioni senza un intervento aggiuntivo di stabilizzazione laterale: un dato interessante sulla percezione del paziente, da leggere come spunto, non come regola valida per ogni tecnica chirurgica."],"pazienti":["Un gruppo di pazienti operati di legamento crociato anteriore è stato seguito per quasi sei anni, confrontando il ginocchio operato con quello sano dell'altra gamba.","Anche quando i controlli medici erano buoni, molti pazienti continuavano a sentire una piccola differenza fra le due gambe. La cosa più interessante: chi si sentiva più sicuro e pronto psicologicamente percepiva meno questa differenza.","Non è un segno che qualcosa sia andato storto nell'intervento: è un promemoria che riprendersi bene dopo un intervento al ginocchio significa curare anche la parte psicologica, non solo quella fisica."]},"linkedin":{"chir":["Coorte retrospettiva, 69 pazienti, confronto within-patient a 68,5±3,3 mesi da ricostruzione isolata del LCA (hamstring): FJS-12 significativamente più basso nel ginocchio operato vs controlaterale sano (81,2±6,4 vs 90,1±5,0; p<0,001).","ACL-RSI correla fortemente con FJS-12 del ginocchio operato (rho=0,786; p<0,001) e ne è predittore indipendente (β=0,833; p<0,001). Mediazione significativa fra pivot-shift residuo e FJS-12 attraverso l'ACL-RSI.","Limite: solo innesto hamstring, ricostruzione isolata senza tenodesi laterale — non direttamente trasferibile a innesto quadricipitale/retto femorale con augmentazione laterale sistematica. Alimenta la tensione sul criterio di rientro oltre la sola stabilità clinica."],"misto":["Uno studio su 69 pazienti mostra che il ginocchio ricostruito resta percepito come diverso dal sano anche a distanza di anni, e che la prontezza psicologica del paziente è il fattore che più spiega questa percezione.","Un dato utile per chi segue la riabilitazione dopo un intervento al crociato: la componente psicologica merita attenzione quanto quella fisica.","Riguarda solo un tipo di innesto: un'indicazione di direzione, da confermare su altre tecniche."],"pazienti":["Uno studio su pazienti operati di legamento crociato anteriore mostra che il ginocchio operato può restare percepito come «diverso» anche a distanza di anni, pur con buoni risultati clinici.","Il fattore più legato a questa percezione è la fiducia psicologica del paziente nel proprio ginocchio.","Un motivo in più per non trascurare l'aspetto psicologico della riabilitazione."]},"instagram":{"chir":["69 pazienti, 5-6 anni dopo ricostruzione isolata del LCA (hamstring): FJS-12 più basso nel ginocchio operato vs sano (81,2 vs 90,1; p<0,001); la prontezza psicologica (ACL-RSI) è il predittore più forte.","Limite: solo hamstring, nessuna tenodesi laterale — trasferibilità al tuo innesto e alla tua augmentazione da verificare.","Fonte: Knee Surgery, Sports Traumatology, Arthroscopy, settembre 2026 — link a PubMed nella scheda dell'app."],"misto":["Anche a distanza di anni, il ginocchio operato di crociato resta percepito come un po' diverso dal sano — e la fiducia psicologica del paziente sembra il fattore che più conta.","Uno studio su un solo tipo di innesto: un'indicazione da confermare su altre tecniche.","Un aspetto da non trascurare nel percorso riabilitativo condiviso fra chirurgo, fisioterapista e paziente."],"pazienti":["Dopo l'intervento al crociato, alcuni pazienti continuano a sentire il ginocchio operato un po' diverso da quello sano, anche con buoni risultati clinici.","Chi si sente più sicuro psicologicamente tende a percepire meno questa differenza: la riabilitazione conta anche a livello mentale.","Parlane con il tuo fisioterapista se questa sensazione persiste: fa parte del percorso, non è un campanello d'allarme."]},"reel":{"chir":["[69 pazienti, quasi 6 anni dopo il LCA] Il ginocchio operato resta meno «dimenticato» di quello sano.","[FJS-12: 81,2 vs 90,1, p<0,001] La prontezza psicologica spiega la differenza più della stabilità clinica.","[Solo innesto hamstring, no tenodesi laterale] Non ancora trasferibile alla tua tecnica."],"misto":["[Legamento crociato, 6 anni dopo] Il ginocchio operato si sente ancora un po' diverso da quello sano.","[La fiducia conta] Chi si sente psicologicamente pronto percepisce meno la differenza.","[Uno studio, un innesto] Un'indicazione da confermare, non ancora una regola generale."],"pazienti":["[Dopo l'intervento al crociato] Il ginocchio operato può sentirsi diverso da quello sano, anche anni dopo.","[La mente conta quanto il corpo] Chi si sente più sicuro percepisce meno la differenza.","[Riabilitazione anche psicologica] Non solo esercizi fisici."]}},"4":{"video":{"chir":["Uno studio biomeccanico ha confrontato 22 pazienti operati di ricostruzione del legamento crociato anteriore con 16 controlli sani, durante un atterraggio monopodalico ad alto rischio, con salto laterale. Usando l'elettromiografia di superficie su 14 muscoli e una scomposizione matematica in «sinergie» muscolari, i ricercatori hanno cercato pattern di coordinazione, non solo di forza.","Nel ginocchio operato il quadricipite lavora troppo prima dell'atterraggio, il contributo di glutei e semimembranoso è ridotto, e dopo l'atterraggio il reclutamento della sinergia dominata dal ginocchio si ritarda, con una ridistribuzione verso glutei, gastrocnemio e tibiale anteriore. Il dato più rilevante: durante l'impatto manca una sinergia dedicata alla stabilizzazione sul piano frontale, quella che coinvolge gluteo medio e peroneo lungo — presente invece nei controlli sani.","È un campione piccolo, l'innesto usato non è specificato, e l'abstract non riporta valori di significatività per i singoli confronti, solo la direzione dell'effetto. Ma il messaggio per la pratica è chiaro: il controllo neuromuscolare centrale può restare alterato anche quando angoli e forze sembrano recuperare, e l'allenamento del rientro dovrebbe mirare proprio a questa sinergia mancante."],"misto":["Uno studio di laboratorio ha guardato come si coordinano fra loro i muscoli della gamba, non solo quanto sono forti, durante un salto impegnativo in persone operate al legamento crociato anteriore, confrontate con persone che non si sono mai infortunate.","Il risultato: nel ginocchio operato manca uno schema muscolare specifico, che nei ginocchi sani aiuta a stabilizzare lateralmente l'articolazione durante l'atterraggio. In pratica, anche se la forza torna quasi normale, il modo in cui i muscoli lavorano insieme può restare diverso.","È uno studio piccolo, di laboratorio, non ancora collegato a un esito clinico concreto come il reinfortunio: indica però una direzione precisa per l'allenamento del rientro allo sport, oltre alla sola misura della forza."],"pazienti":["Una ricerca ha osservato come lavorano insieme i muscoli della gamba durante un salto, confrontando persone operate al legamento crociato del ginocchio con persone che non si sono mai infortunate.","È emerso che, anche quando la forza è tornata quasi normale, i muscoli della gamba operata possono continuare a coordinarsi in modo un po' diverso durante un atterraggio, soprattutto nel controllo laterale del ginocchio.","È un motivo in più per continuare gli esercizi di equilibrio e controllo del movimento anche dopo che il ginocchio sembra «guarito», e non fermarsi solo al recupero della forza muscolare."]},"linkedin":{"chir":["Studio caso-controllo biomeccanico, 22 pazienti dopo ACLR unilaterale vs 16 controlli sani, atterraggio monopodalico con salto laterale ad alto rischio; EMG di superficie 14 muscoli, scomposizione in sinergie (NMF), modelli OpenSim.","Ginocchio operato: peso pre-atterraggio eccessivo sul quadricipite, contributo ridotto di glutei/semimembranoso, reclutamento ritardato della sinergia ginocchio-dominante, assenza di una sinergia di stabilizzazione frontale (gluteo medio/peroneo lungo) presente nei controlli.","Limiti: campione piccolo, innesto non specificato, nessun valore di significatività riportato per i singoli confronti. Un argomento per allenamenti di rientro mirati alla sinergia frontale mancante, oltre alla sola forza."],"misto":["Uno studio biomeccanico mostra che, dopo la ricostruzione del legamento crociato anteriore, i muscoli della gamba possono coordinarsi in modo diverso durante un atterraggio ad alto rischio, in particolare nella stabilizzazione laterale del ginocchio.","Un dato utile per chi programma la riabilitazione: la sola forza muscolare recuperata non garantisce che la coordinazione sia tornata come prima.","Studio piccolo e di laboratorio: indica una direzione, non ancora un protocollo definitivo."],"pazienti":["Una ricerca mostra che, dopo l'intervento al legamento crociato, i muscoli della gamba possono coordinarsi in modo un po' diverso durante un salto, anche quando la forza è tornata quasi normale.","Un motivo in più per non fermare la riabilitazione ai soli esercizi di forza.","Studio di laboratorio, su un campione piccolo: un segnale da approfondire."]},"instagram":{"chir":["22 operati di LCA vs 16 controlli: analisi delle sinergie muscolari durante un atterraggio ad alto rischio. Manca, nel ginocchio operato, una sinergia di stabilizzazione sul piano frontale (gluteo medio/peroneo lungo).","Campione piccolo, innesto non specificato, nessun p-value per i singoli confronti. Un argomento per allenare quella sinergia mancante nel rientro allo sport.","Fonte: Medicine and Science in Sports and Exercise, settembre 2026 — link a PubMed nella scheda dell'app."],"misto":["Dopo l'intervento al crociato, i muscoli della gamba possono coordinarsi in modo diverso durante un salto, anche con la forza tornata quasi normale.","Uno studio piccolo, di laboratorio: indica dove indirizzare l'allenamento del rientro allo sport.","Utile per chi segue la riabilitazione: un argomento in più per non fermarsi alla sola misura della forza."],"pazienti":["Anche quando la forza è tornata, il modo in cui i muscoli della gamba lavorano insieme può restare un po' diverso dopo l'intervento al crociato.","Un motivo per continuare gli esercizi di equilibrio, non solo di forza, nella riabilitazione.","Parlane con il tuo fisioterapista per includere esercizi di equilibrio nel programma di rientro."]},"reel":{"chir":["[22 operati di LCA vs 16 controlli] Manca una sinergia muscolare di stabilizzazione frontale nell'atterraggio.","[EMG + scomposizione in sinergie] Quadricipite iperattivo prima, ritardo dopo l'atterraggio.","[Campione piccolo, no p-value] Un segnale per l'allenamento del rientro, non ancora una prova."],"misto":["[Dopo il crociato] I muscoli della gamba si coordinano in modo diverso durante un salto.","[Anche con la forza tornata] Manca uno schema di stabilizzazione laterale del ginocchio.","[Studio di laboratorio] Indica una direzione per la riabilitazione."],"pazienti":["[Dopo l'intervento al crociato] I muscoli possono coordinarsi diversamente durante un salto.","[Anche se la forza torna] L'equilibrio muscolare può restare da allenare.","[Non fermarti alla sola forza] Continua gli esercizi di equilibrio nella riabilitazione."]}},"5":{"video":{"chir":["Uno studio biomeccanico su modello porcino ha confrontato quattro modi diversi di riparare la radice posteriore del menisco mediale: due configurazioni di sutura, doppio-cinch e Mason-Allen modificato, ciascuna fissata con placca corticale o con ancora knotless. In totale 28 menischi, 7 per gruppo, testati a carico crescente fino al cedimento.","Il risultato: nessuna differenza statisticamente significativa fra i quattro costrutti su rigidità, carico di snervamento, carico massimo o carico ultimo — tutti i valori di p fra 0,11 e 0,35. In ogni gruppo, il cedimento è avvenuto sempre nello stesso punto: l'interfaccia fra il filo di sutura e il tessuto del menisco, mai per rottura dell'ancoraggio osseo.","È uno studio muto, non uno studio di equivalenza: sette campioni per gruppo, a tempo zero, senza carico ciclico prolungato né guarigione biologica, non hanno la potenza per escludere una differenza reale. E nessuna delle due fissazioni testate è la tecnica transtibiale pull-out che si usa nella pratica clinica abituale per questo tipo di riparazione."],"misto":["Un esperimento di laboratorio su tessuto animale ha confrontato quattro modi di riparare la parte posteriore del menisco, quella più vicina al centro del ginocchio: due modi di cucire il filo di sutura, e due modi di fissarlo all'osso della tibia.","Il risultato è che nessuna delle quattro combinazioni si è dimostrata chiaramente migliore delle altre: la resistenza del punto di riparazione è risultata simile in tutti i gruppi. Il punto che cede per primo, sempre, è dove il filo attraversa il tessuto del menisco — non il nodo, non l'ancoraggio nell'osso.","È un esperimento con pochi campioni per gruppo, che misura solo la resistenza immediata, prima che il tessuto inizi a guarire: informa su come si comportano meccanicamente queste tecniche, ma non dimostra che siano davvero equivalenti in un paziente reale."],"pazienti":["Un esperimento di laboratorio, su tessuto di menisco animale, ha confrontato diversi modi di riparare la parte interna del menisco quando si strappa vicino alla sua radice.","Nessuna delle tecniche confrontate è risultata chiaramente più resistente delle altre nell'esperimento; il punto più debole, in tutti i casi, è risultato essere dove il filo di sutura passa attraverso il tessuto del menisco stesso.","È un esperimento di laboratorio, non uno studio su pazienti: aiuta i ricercatori a capire come migliorare le tecniche di riparazione, ma non dice ancora quale sia la scelta migliore per una persona reale."]},"linkedin":{"chir":["Modello porcino controllato, 28 menischi mediali, 4 costrutti di riparazione della radice posteriore (doppio-cinch/Mason-Allen modificato × placca corticale/ancora knotless), test a carico crescente fino a cedimento.","Nessuna differenza significativa fra i gruppi su rigidità (p=0,25), carico di snervamento (p=0,12), carico massimo (p=0,11) o ultimo (p=0,14); cedimento sempre per elongazione all'interfaccia menisco-sutura.","Studio muto: 7 campioni per gruppo, tempo zero, nessuna guarigione biologica — l'assenza di differenza non dimostra equivalenza. Nessuna delle due fissazioni è la tecnica transtibiale pull-out di uso corrente."],"misto":["Un esperimento di laboratorio confronta quattro tecniche per riparare la radice del menisco: nessuna risulta chiaramente superiore alle altre.","Il punto debole è sempre dove il filo attraversa il tessuto del menisco, non il nodo o l'ancoraggio osseo.","Studio a tempo zero, su tessuto animale, con pochi campioni: informativo sulla meccanica, non conclusivo sulla scelta clinica."],"pazienti":["Un esperimento di laboratorio confronta diverse tecniche per riparare il menisco del ginocchio quando si strappa vicino al centro dell'articolazione.","Nessuna tecnica è risultata chiaramente migliore delle altre; il punto debole è sempre il tessuto stesso, non il materiale di fissazione.","È un esperimento su tessuto animale, non ancora uno studio su pazienti."]},"instagram":{"chir":["28 menischi porcini, 4 costrutti di riparazione della radice: nessuna differenza biomeccanica significativa (p 0,11-0,35), cedimento sempre all'interfaccia menisco-sutura.","Studio muto (n=7/gruppo, tempo zero): l'assenza di differenza non è equivalenza. Nessuna fissazione testata è la tecnica pull-out transtibiale corrente.","Fonte: Journal of ISAKOS, settembre 2026 — link a PubMed nella scheda dell'app."],"misto":["Un esperimento di laboratorio confronta tecniche per riparare la radice del menisco: nessuna risulta chiaramente migliore.","Il punto debole resta sempre il tessuto del menisco, non il filo o l'ancoraggio.","Un dato tecnico utile per chi segue da vicino la chirurgia del menisco, dal chirurgo al fisioterapista."],"pazienti":["Un esperimento su tessuto animale confronta diverse tecniche per riparare il menisco vicino al centro del ginocchio.","Il punto più debole è sempre il tessuto stesso: un dato di laboratorio, non ancora clinico.","Se devi riparare il menisco, chiedi pure al tuo chirurgo quale tecnica userà e perché."]},"reel":{"chir":["[28 menischi porcini, 4 costrutti] Nessuna differenza biomeccanica significativa fra le tecniche di riparazione della radice.","[p fra 0,11 e 0,35] Il cedimento è sempre all'interfaccia menisco-sutura.","[Studio muto, n=7/gruppo] L'assenza di differenza non prova l'equivalenza clinica."],"misto":["[Radice del menisco, laboratorio] Quattro tecniche di riparazione a confronto: nessuna vince chiaramente.","[Il punto debole] È sempre il tessuto del menisco, non il filo.","[Studio a tempo zero] Informativo, non ancora conclusivo per la pratica."],"pazienti":["[Riparare il menisco] Un esperimento di laboratorio confronta diverse tecniche.","[Il punto debole] È sempre il tessuto stesso del menisco.","[Non ancora sui pazienti] Solo un esperimento su tessuto animale."]}}};
var TAGS={"1":{"linkedin":"#Ortopedia #ProtesiGinocchio #ChirurgiaOrtopedica","instagram":"#ginocchio #protesiginocchio #ortopedia #chirurgiaortopedica #artroplastica #ricercamedica #infezione #registrosvizzero #saluteginocchio","kw":"rischio infezione protesi ginocchio, protesi dopo intervento precedente"},"2":{"linkedin":"#PrevenzioneInfortuni #MedicinaSportiva #Ginocchio","instagram":"#prevenzioneinfortuni #allenamentoneuromuscolare #ginocchio #medicinasportiva #sport #ricercascientifica #lca #ortopedia #fisioterapia","kw":"prevenzione infortuni ginocchio, allenamento neuromuscolare sport"},"3":{"linkedin":"#LCA #RiabilitazioneGinocchio #ChirurgiaOrtopedica","instagram":"#legamentocrociato #lca #riabilitazione #ginocchio #chirurgiaortopedica #psicologiadellosport #ricercamedica #ritornosport #kneesurgery","kw":"recupero psicologico crociato, ginocchio dopo intervento LCA"},"4":{"linkedin":"#Biomeccanica #LCA #RientroSport","instagram":"#biomeccanica #lca #legamentocrociato #rientrosport #riabilitazione #controlloneuromuscolare #ortopedia #medicinasportiva #ricercascientifica","kw":"biomeccanica dopo LCA, controllo muscolare ginocchio, rientro sport dopo crociato"},"5":{"linkedin":"#Menisco #Biomeccanica #ChirurgiaGinocchio","instagram":"#menisco #biomeccanica #chirurgiaginocchio #ortopedia #ricercascientifica #suturamenisco #kneesurgery #medicinasportiva #artroscopia","kw":"riparazione radice menisco, sutura menisco tecnica chirurgica"}};
var NLB={"1":{"prof":["Il registro svizzero quantifica il rischio infettivo della protesi dopo un ginocchio già operato","Coorte di registro nazionale (Swiss Implant Registry) su 121.692 protesi totali di ginocchio: chi aveva già subito un intervento omolaterale (osteotomia, LCA, sinovectomia, chirurgia per infezione) va incontro a una revisione per infezione periprotesica più frequente (OR procedura-specifici da 1,44 a 3,30), con un salto significativo oltre i due interventi precedenti (OR 2,01; IC 95% 1,51-2,68).","Dati di registro, senza dettagli su tecnica o innesto degli interventi precedenti: un argomento in più per la stratificazione preoperatoria del rischio, non una controindicazione."],"mix":["Chi ha già operato quel ginocchio rischia di più con la protesi totale","Un grande registro nazionale svizzero, oltre 120.000 protesi di ginocchio, mostra che i pazienti già operati in passato allo stesso ginocchio — per un legamento, per correggere l'asse della gamba o per un'infezione — hanno una probabilità più alta di dover essere rioperati per infezione dopo la protesi totale, tanto più alta quanti più interventi hanno avuto prima.","È un dato di registro, non uno studio clinico dedicato: non dice come intervenire, dice solo che la storia chirurgica del ginocchio va conosciuta e discussa prima della protesi, non solo l'età o il peso del paziente."],"paz":["Un ginocchio già operato conta nella scelta prima della protesi","Uno studio su oltre 120.000 protesi di ginocchio in Svizzera mostra che chi ha già avuto un intervento sullo stesso ginocchio in passato ha una probabilità leggermente più alta di complicazioni infettive dopo la protesi, soprattutto se gli interventi precedenti sono stati più di due.","Non significa che chi ha già operato il ginocchio non possa fare la protesi con successo: significa che la storia chirurgica di quel ginocchio è un'informazione utile da portare al colloquio con il chirurgo, insieme alle altre."],"kw":"protesi ginocchio rischio infezione, revisione protesi ginocchio, chirurgia ginocchio precedente"},"2":{"prof":["L'allenamento neuromuscolare riduce gli infortuni al ginocchio, senza distinzione di età","Meta-analisi di 30 studi (RCT e non randomizzati) sull'allenamento neuromuscolare per la prevenzione degli infortuni al ginocchio nello sport: riduzione significativa del rischio (effect estimate 0,670; IC 95% 0,547-0,820), protettivo sia sopra sia sotto i 18 anni, con vantaggio per i programmi multicomponente (0,643) e standardizzati (0,592) rispetto a quelli generici.","Analisi su dose e componenti dichiarate esplorative dagli stessi autori: un'indicazione di direzione, non un protocollo definitivo da prescrivere senza adattamento."],"mix":["Prevenire gli infortuni al ginocchio nello sport: l'allenamento neuromuscolare funziona a ogni età","Una revisione di 30 studi scientifici mostra che i programmi di allenamento neuromuscolare — esercizi di equilibrio all'atterraggio, pliometria, rinforzo del core e degli arti inferiori — riducono il rischio di infortunio al ginocchio negli sportivi, con risultati simili fra adolescenti e adulti. I programmi più strutturati e con più componenti insieme funzionano meglio di quelli generici.","Gli autori stessi avvertono che le indicazioni su quanto e come allenarsi restano da confermare con altri studi: la direzione del beneficio è solida, i dettagli pratici vanno ancora affinati."],"paz":["Allenare il ginocchio prima dell'infortunio, non solo dopo","Una revisione di molti studi scientifici conferma che alcuni programmi di allenamento specifico — equilibrio, salti controllati, rinforzo muscolare — riducono il rischio di farsi male al ginocchio nello sport, sia nei ragazzi che negli adulti.","È una buona notizia soprattutto per chi ha figli sportivi o pratica sport a rischio di torsione del ginocchio: prevenire con un allenamento mirato ha un fondamento scientifico solido, anche se i dettagli del programma ideale sono ancora in discussione."],"kw":"prevenzione infortuni ginocchio, allenamento neuromuscolare sport, prevenzione lesioni LCA"},"3":{"prof":["Anche a 5 anni, il ginocchio ricostruito resta meno «dimenticato» del sano","Coorte retrospettiva su 69 pazienti dopo ricostruzione isolata del LCA con hamstring, confronto within-patient a 68,5±3,3 mesi: Forgotten Joint Score-12 inferiore nel ginocchio operato (81,2±6,4 contro 90,1±5,0; p<0,001); la prontezza psicologica (ACL-RSI) è il predittore più forte della consapevolezza articolare residua (β=0,833; p<0,001).","Solo innesto di hamstring, ricostruzione isolata senza tenodesi laterale: non trasferibile senza verifica al tuo innesto né alla tua augmentazione sistematica."],"mix":["Il crociato ricostruito bene resta comunque un po' diverso da quello sano","Uno studio su 69 pazienti, rivisti in media quasi sei anni dopo la ricostruzione del legamento crociato anteriore, mostra che il ginocchio operato — anche quando funziona bene — resta percepito come leggermente diverso dal ginocchio sano dell'altra gamba. Il fattore che più spiega questa differenza non è la stabilità misurata dal medico, ma quanto il paziente si sente psicologicamente pronto.","Lo studio riguarda solo un tipo di innesto (hamstring, senza rinforzo laterale aggiuntivo): un dato interessante sulla percezione del paziente, da confermare su altre tecniche prima di generalizzarlo."],"paz":["Perché, anni dopo, si sente ancora che il ginocchio operato «c'è»","Uno studio su pazienti operati di legamento crociato anteriore, seguiti per quasi sei anni, mostra che molti continuano a percepire una piccola differenza fra il ginocchio operato e quello sano, anche quando i test clinici sono buoni. Chi si sente psicologicamente più pronto e sicuro tende a percepire meno questa differenza.","Non è un segno che qualcosa sia andato storto: è un promemoria che la ripresa dopo un intervento al crociato ha anche una componente psicologica, che vale la pena affrontare insieme alla riabilitazione fisica."],"kw":"recupero legamento crociato, riabilitazione psicologica LCA, ginocchio dopo intervento"},"4":{"prof":["Dopo il crociato, manca una sinergia muscolare di stabilizzazione frontale all'atterraggio","Analisi delle sinergie muscolari (fattorizzazione a matrici non negative, 14 muscoli) in 22 operati di LCA contro 16 controlli durante un atterraggio ad alto rischio: peso pre-atterraggio eccessivo sul quadricipite, reclutamento ritardato della sinergia dominata dal ginocchio, e assenza — nel ginocchio operato — di una sinergia dedicata alla stabilizzazione sul piano frontale (gluteo medio/peroneo lungo).","Campione piccolo, innesto non specificato, nessun valore di significatività riportato per i singoli confronti: un segnale meccanicistico da confermare, non un dato pronto per la pratica."],"mix":["Dopo l'intervento al crociato, i muscoli del ginocchio si coordinano in modo diverso quando si atterra da un salto","Uno studio biomeccanico ha analizzato come si attivano insieme i muscoli della gamba durante un atterraggio impegnativo in chi ha ricostruito il legamento crociato anteriore. Rispetto a chi non ha mai avuto infortuni, manca uno schema muscolare specifico che aiuta a stabilizzare il ginocchio lateralmente — un dettaglio che la sola misura della forza non coglie.","È uno studio piccolo e di laboratorio, non ancora legato a un esito clinico come il reinfortunio: indica una direzione per l'allenamento post-operatorio, non una prova definitiva."],"paz":["Il ginocchio riabilitato può muoversi bene e coordinarsi comunque in modo diverso","Una ricerca di laboratorio mostra che, dopo l'intervento al legamento crociato, i muscoli della gamba possono continuare a lavorare insieme in modo leggermente diverso durante un salto o un atterraggio, anche quando la forza è tornata quasi normale.","È un motivo in più per non fermare la riabilitazione alla sola palestra: gli esercizi di equilibrio e di controllo del movimento restano importanti anche quando il ginocchio sembra «guarito» sulla carta."],"kw":"riabilitazione dopo crociato, controllo neuromuscolare ginocchio, rientro sport dopo LCA"},"5":{"prof":["Sutura della radice meniscale: doppio-cinch e Mason-Allen si equivalgono a tempo zero, su modello porcino","Modello porcino controllato, 28 menischi mediali, 4 costrutti (doppio-cinch/Mason-Allen modificato × placca corticale/ancora knotless): nessuna differenza statisticamente significativa su rigidità, carico di snervamento, carico massimo o ultimo (p fra 0,11 e 0,35); cedimento sempre per elongazione all'interfaccia menisco-sutura.","Studio muto: 7 campioni per gruppo, tempo zero, nessuna delle due fissazioni è la tecnica transtibiale pull-out — l'assenza di differenza non dimostra equivalenza clinica."],"mix":["Riparare la radice del menisco: due modi di cucire il filo danno lo stesso risultato in laboratorio","Uno studio di laboratorio su menischi animali confronta due tecniche di sutura e due modi di fissare il filo alla tibia nella riparazione della radice del menisco: nessuna combinazione risulta chiaramente migliore delle altre, e il punto più debole è sempre dove il filo attraversa il tessuto del menisco, non il nodo o l'ancoraggio.","È un esperimento di laboratorio a tempo zero, su tessuto animale e con pochi campioni per gruppo: informativo sulla meccanica, non dimostra che le tecniche siano davvero equivalenti nel paziente."],"paz":["Anche in laboratorio, il punto debole della riparazione del menisco è il tessuto, non il filo","Uno studio sperimentale su tessuto animale, che confronta diverse tecniche per riparare la parte interna del menisco, mostra che il punto che cede per primo è sempre dove il filo di sutura passa attraverso il menisco stesso, non il nodo o l'ancoraggio usati.","È un esperimento di laboratorio, non uno studio su pazienti: aiuta a capire come si comportano meccanicamente le tecniche di riparazione, non a scegliere fra loro nella pratica clinica."],"kw":"riparazione radice menisco, sutura menisco tecnica, chirurgia menisco ginocchio"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Un ginocchio già operato rischia più infezione dopo la protesi",v:"Registro nazionale svizzero su 121.692 protesi totali: chi aveva già subito un intervento sullo stesso ginocchio (osteotomia, LCA, sinovectomia, infezione pregressa) va incontro a una revisione per infezione più frequente, in proporzione al numero di interventi precedenti.",ax:"Elsheikh, Christen, Hirschmann",date:"set 2026",meta:"coorte di registro nazionale, 121.692 protesi · [III]",pmid:'42735046',doi:'10.1002/ksa.70599',journal:"Knee Surgery, Sports Traumatology, Arthroscopy",authors:"Elsheikh R, Amsler F, Brand C, Christen B, Hirschmann MT",design:"Coorte retrospettiva su tutto il registro nazionale svizzero degli impianti (Swiss Implant Registry, SIRIS), protesi totali di ginocchio primarie 2015-2022, regressione logistica multivariabile aggiustata per età, sesso, BMI e classe ASA, con analisi procedura-specifica dei precedenti interventi omolaterali e analisi del carico chirurgico cumulativo.",pop:"121.692 protesi totali di ginocchio primarie; 40.535 (33,3%) con almeno un precedente intervento omolaterale sullo stesso ginocchio (osteotomia tibiale, ricostruzione del LCA, sinovectomia, osteosintesi tibiale, chirurgia per infezione).",results:"Qualunque intervento precedente: revisione per qualunque causa OR 1,33 (IC 95% 1,25-1,42; p<0,001), revisione per infezione periprotesica OR 1,22 (IC 95% 1,06-1,42; p=0,005). Per tipo di intervento: chirurgia per infezione del ginocchio OR 3,30 (IC 95% 1,56-6,96; p=0,002), osteotomia tibiale OR 2,12 (IC 95% 1,60-2,82), sinovectomia OR 2,18 (IC 95% 1,27-3,73), osteosintesi tibiale OR 1,71 (IC 95% 1,10-2,68), ricostruzione del LCA OR 1,44 (IC 95% 1,10-1,90; tutti p<0,05). Il rischio di infezione sale in modo significativo solo con più di due interventi precedenti (OR 2,01; IC 95% 1,51-2,68; p<0,001).",concl:"Gli autori concludono che la chirurgia omolaterale precedente comporta un rischio di revisione procedura-specifico e cumulativo, e che la storia chirurgica va integrata nella stratificazione del rischio preoperatorio prima della protesi totale.",limits:"Dati di registro/amministrativi, senza esame clinico diretto né dettagli su tecnica o innesto degli interventi precedenti — per il LCA non è specificato l'innesto né se comprendesse un gesto extra-articolare laterale · confondimento per indicazione possibile: un ginocchio più volte operato può avere una patologia di base più complessa, non solo più interventi · registro svizzero, generalizzabilità ad altri sistemi non verificata qui.",perte:"Riguarda direttamente due dei tuoi interventi più frequenti — ricostruzione del LCA e osteotomia — nel momento in cui, anni dopo, quel ginocchio arriva alla protesi totale: la storia chirurgica pregressa, non solo età o BMI, va discussa nel colloquio preoperatorio come fattore di rischio infettivo quantificabile. Lo studio non dice se la tua tenodesi laterale sistematica incida separatamente dall'ACLR isolata."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Frontiers in Public Health",h:"L'allenamento neuromuscolare riduce gli infortuni al ginocchio a ogni età",v:"Meta-analisi di 30 studi: i programmi di allenamento neuromuscolare multicomponente e standardizzati riducono il rischio di infortunio al ginocchio negli atleti, senza una differenza chiara fra maggiorenni e minorenni.",ax:"Yao, Pan, Niu",date:"set 2026",meta:"revisione sistematica e meta-analisi, 30 studi · [II]",pmid:'42730390',doi:'10.3389/fpubh.2026.1822715',journal:"Frontiers in Public Health",authors:"Yao Y, Pan M, Niu X",design:"Revisione sistematica e meta-analisi (protocollo PROSPERO, PRISMA) di programmi di allenamento neuromuscolare (NMT) per la prevenzione degli infortuni al ginocchio nello sport; ricerca su cinque banche dati fino al 30 settembre 2025; meta-analisi a effetti casuali, sottogruppi per età e caratteristiche del programma, meta-regressione, rischio di bias con RoB 2 e ROBINS-I.",pop:"30 studi inclusi (RCT e studi non randomizzati), popolazione atletica mista, sopra e sotto i 18 anni.",results:"L'NMT riduce significativamente il rischio di infortunio al ginocchio (effect estimate 0,670; IC 95% 0,547-0,820; p<0,001), eterogeneità moderata (I²=58,5%). Effetto protettivo sia sopra i 18 anni (0,566) sia a 18 anni o meno (0,718), senza differenza significativa fra i sottogruppi; la meta-regressione non trova un effetto moderatore dell'età media né della proporzione femminile. I programmi multicomponente (≥3 elementi fra stabilizzazione all'atterraggio, pliometria, core, agilità, forza) riducono il rischio (0,643), quelli con meno di 3 componenti no (differenza fra sottogruppi p=0,045); i programmi standardizzati riducono il rischio (0,592), i non standardizzati no.",concl:"Gli autori concludono che l'NMT riduce il rischio di infortunio al ginocchio negli atleti senza una chiara modulazione da parte dell'età, e che programmi strutturati, multicomponente e standardizzati possono avere un vantaggio pratico — ma invitano a leggere i dati su dose e componenti con cautela, perché quelle analisi erano esplorative.",limits:"Disegni eterogenei, RCT e studi non randomizzati analizzati insieme · le analisi su dose, componenti e standardizzazione sono dichiarate esplorative dagli stessi autori, non confermatorie · l'esito è «infortunio al ginocchio» in generale, non specificamente la rottura o la revisione del LCA.",perte:"Non è una tua tecnica chirurgica, ma tocca la prevenzione primaria nella fascia d'età che segui dai 14 anni in su: un argomento concreto — programma multicomponente, standardizzato, oltre 25 settimane — da portare ai pazienti giovani sportivi e ai loro preparatori, prima ancora che arrivino sul tuo tavolo operatorio."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Il ginocchio operato resta meno «dimenticato» di quello sano",v:"69 pazienti, 5-6 anni dopo la ricostruzione isolata del LCA con hamstring: il ginocchio operato ha una consapevolezza articolare peggiore del controlaterale sano, e la prontezza psicologica ne è il predittore più forte.",ax:"Uslu, Ergişi, Daşar",date:"set 2026",meta:"coorte retrospettiva comparativa, 69 pazienti · [III]",pmid:'42735053',doi:'10.1002/ksa.70604',journal:"Knee Surgery, Sports Traumatology, Arthroscopy",authors:"Uslu MB, Ergişi Y, Gökalp B, Çömez O, Altun O, Daşar U",design:"Coorte retrospettiva monocentrica, confronto within-patient fra ginocchio ricostruito e controlaterale sano, ricostruzione isolata del LCA con autoinnesto di hamstring (esclusi interventi associati su menisco, cartilagine, altri legamenti, tenodesi laterale o innesti diversi), follow-up minimo 5 anni; regressione multivariabile e analisi di mediazione.",pop:"69 pazienti, follow-up medio 68,5±3,3 mesi.",results:"Forgotten Joint Score-12 significativamente più basso nel ginocchio ricostruito rispetto al controlaterale sano (81,2±6,4 contro 90,1±5,0; p<0,001). L'instabilità residua si associa a punteggi peggiori di ACL-RSI, FJS-12, IKDC e Lysholm (tutti p<0,001). La prontezza psicologica (ACL-RSI) correla fortemente con il FJS-12 del ginocchio operato (rho=0,786; p<0,001) e ne è predittore indipendente (β=0,833; p<0,001), così come della differenza fra i due ginocchi (β=0,668; p<0,001); l'analisi di mediazione mostra un'associazione indiretta significativa fra pivot-shift residuo e FJS-12 attraverso l'ACL-RSI (IC bootstrap 95% da -11,06 a -5,29).",concl:"Gli autori concludono che, pur con esiti funzionali e stabilità oggettiva buoni nella maggioranza dei pazienti, il ginocchio ricostruito resta percettivamente inferiore al controlaterale sano, e che la prontezza psicologica media la relazione fra instabilità rotazionale residua e mancata «dimenticanza» del ginocchio.",limits:"Livello III, solo innesto di hamstring: non trasferibile senza verifica al tendine quadricipitale/retto femorale né alla tenodesi extra-articolare laterale, qui esplicitamente esclusa dai criteri di inclusione · disegno retrospettivo monocentrico, un solo centro turco · l'analisi di mediazione suggerisce un meccanismo ma non lo dimostra causalmente.",perte:"Alimenta la tensione T3 con un dato diretto sul «ginocchio dimenticato»: anche a 5-6 anni e con esiti oggettivi buoni, la percezione soggettiva del paziente resta indietro, e la prontezza psicologica — non solo la stabilità clinica — sembra spiegarla più di ogni altra cosa. Non riguarda però né il tuo innesto né la tua augmentazione laterale sistematica: da leggere come ipotesi da verificare sulla tua popolazione, non come dato già trasferibile."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Medicine and Science in Sports and Exercise",h:"Dopo il crociato, il ginocchio atterra con un comando muscolare diverso",v:"22 pazienti operati di LCA contro 16 controlli: l'analisi delle sinergie muscolari durante un atterraggio ad alto rischio mostra un comando neuromuscolare centrale alterato, in particolare l'assenza di una sinergia dedicata alla stabilizzazione sul piano frontale.",ax:"Gong, Zhang, Ao",date:"set 2026",meta:"studio caso-controllo biomeccanico, 22 pazienti/16 controlli · [IV]",pmid:'42735362',doi:'10.1249/MSS.0000000000004147',journal:"Medicine and Science in Sports and Exercise",authors:"Gong Z, Han Y, Li T, Li Y, Zhang M, Li L, Ao D",design:"Studio caso-controllo biomeccanico: 22 pazienti dopo ricostruzione unilaterale del LCA (arto operato e non operato) e 16 controlli sani, compito di atterraggio monopodalico con salto laterale ad alto rischio; elettromiografia di superficie su 14 muscoli, cinematica e forze di reazione al suolo; scomposizione in sinergie muscolari (fattorizzazione a matrici non negative) nelle fasi di pre-atterraggio, impatto e carico; modelli muscoloscheletrici OpenSim per angoli e momenti articolari.",pop:"22 pazienti con ricostruzione unilaterale del LCA (innesto non specificato nell'abstract), 16 controlli sani.",results:"Rispetto ai controlli, il ginocchio operato mostra all'atterraggio minore abduzione d'anca e minore flessione plantare di caviglia ma maggiore flessione del ginocchio, con un peso pre-atterraggio eccessivo sul quadricipite e un contributo ridotto di glutei e semimembranoso; dopo l'atterraggio il peso del quadricipite diminuisce e il reclutamento della sinergia dominata dal ginocchio si ritarda, con una ridistribuzione compensatoria su glutei, gastrocnemio e tibiale anteriore. Durante l'impatto, il ginocchio operato manca di una sinergia dedicata alla stabilizzazione sul piano frontale (gluteo medio/peroneo lungo), presente invece nei controlli. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract per i singoli confronti.",concl:"Gli autori concludono che il ginocchio operato mantiene alterazioni persistenti e specifiche del comando neuromuscolare centrale in tutte le fasi dell'atterraggio, correlate a una biomeccanica meno favorevole, e propongono di indirizzare l'allenamento neuromuscolare specificamente sulla sinergia di stabilizzazione frontale mancante.",limits:"Campione piccolo (22 operati, 16 controlli), monocentrico · innesto e tecnica chirurgica non specificati nell'abstract: non è possibile giudicare la trasferibilità al tuo costrutto · nessun valore di significatività statistica riportato per i confronti descritti, solo la direzione dell'effetto.",perte:"Aggiunge alla tensione T3 un livello a monte della semplice simmetria di forza: anche quando angoli e momenti sembrano recuperare, il comando muscolare centrale che li genera può restare alterato, in particolare sul piano frontale del valgo dinamico. Un argomento in più per non fermare il criterio di rientro alla sola forza o alla sola altezza del salto."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Journal of ISAKOS",h:"Due tecniche di sutura della radice meniscale si equivalgono, a tempo zero",v:"Modello porcino, 28 menischi: nessuna differenza biomeccanica fra doppio-cinch e Mason-Allen modificato, né fra placca corticale e ancora knotless — ma il campione è troppo piccolo per escluderla.",ax:"Gravini Amador, Arias Perez, Infante Ardila",date:"set 2026",meta:"studio biomeccanico controllato, modello porcino, 28 campioni · [V]",pmid:'42731677',doi:'10.1016/j.jisako.2026.101219',journal:"Journal of ISAKOS",authors:"Gravini Amador GA, Vallejo Tamayo MJ, Arias Perez RD, Pérez Pabón MM, Castañeda López JF, Hernández Albino A, Infante Ardila J",design:"Studio biomeccanico controllato su modello porcino: 28 menischi mediali randomizzati in quattro costrutti di riparazione della radice meniscale posteriore (doppio-cinch con placca corticale, doppio-cinch con ancora knotless, Mason-Allen modificato con placca corticale, Mason-Allen modificato con ancora knotless); precondizionamento e test a carico crescente fino a cedimento.",pop:"28 menischi mediali porcini, 7 per gruppo, tempo zero — nessun paziente, nessun carico ciclico prolungato né guarigione biologica.",results:"Tutti i campioni hanno ceduto per progressiva elongazione all'interfaccia menisco-sutura. Rigidità mediana 14,0-26,5 N/mm, carico di snervamento 36,7-47,5 N, carico ultimo 135,0-167,0 N a seconda del costrutto — nessuna differenza statisticamente significativa fra i quattro gruppi per rigidità (p=0,25), carico di snervamento (p=0,12), carico massimo (p=0,11), carico ultimo (p=0,14) o spostamento (p=0,33 e p=0,18); nessuna differenza nemmeno raggruppando per sola configurazione di sutura o solo metodo di fissazione.",concl:"Gli autori concludono che i costrutti doppio-cinch e Mason-Allen modificato, con placca corticale o ancora knotless, hanno un comportamento biomeccanico a tempo zero comparabile, e che l'interfaccia menisco-sutura — non la configurazione o la fissazione — sembra il punto debole determinante.",limits:"Studio muto: 7 campioni per gruppo, tempo zero, nessun carico ciclico prolungato né guarigione biologica — su un campione così piccolo l'assenza di differenza non dimostra equivalenza, dice solo che lo studio non ha la potenza per escluderla · modello animale, non tessuto umano · nessuna delle due fissazioni testate è la tua tecnica transtibiale pull-out.",perte:"Tocca il tuo dominio tecnico — la riparazione della radice meniscale — ma non la tua tecnica: qui si confrontano costrutti su ancora (placca corticale o ancora knotless), non il pull-out transtibiale che usi tu. Il messaggio di fondo — l'interfaccia menisco-sutura come punto debole comune, più che la configurazione — resta comunque un promemoria trasversale."}];
var SUGGQ=[{"k":"kol","n":"Michael T. Hirschmann","w":"Kantonsspital Baselland / Università di Basilea, Svizzera","r":"Autore senior dello studio di oggi sul rischio di infezione procedura-specifico dopo protesi totale di ginocchio, sul registro nazionale svizzero (scheda 1): corrispondenza tecnica diretta con la tua pratica di protesi totale robot-assistita (VELYS) e con la stratificazione del rischio preoperatorio nel tuo stesso sistema sanitario. Sostituisce la proposta invariata di Aaron J. Krych (14 settembre)."}];
var BRIEF_TEXT="Oggi cinque lavori, con in apertura un dato di registro che riguarda direttamente due dei tuoi interventi più frequenti: il registro nazionale svizzero degli impianti, su oltre 120.000 protesi totali di ginocchio, mostra che i pazienti già operati in passato allo stesso ginocchio — per un'osteotomia, per il legamento crociato anteriore, per un'infezione — vanno incontro a una revisione per infezione periprotesica più frequente, in proporzione al numero di interventi precedenti; un argomento concreto per il colloquio preoperatorio prima della protesi. Una meta-analisi di 30 studi conferma che l'allenamento neuromuscolare riduce il rischio di infortunio al ginocchio nello sport, a ogni età, con un vantaggio per i programmi multicomponente e standardizzati. Tre lavori toccano invece la tensione sul criterio di rientro dopo il crociato anteriore: uno studio turco mostra che il ginocchio ricostruito resta percepito come «meno dimenticato» del sano anche a distanza di anni, e che la prontezza psicologica ne è il predittore più forte; uno studio biomeccanico cinese mostra che, durante un atterraggio ad alto rischio, manca nel ginocchio operato una sinergia muscolare dedicata alla stabilizzazione laterale; e chiude un esperimento di laboratorio su modello animale che confronta tecniche di sutura della radice meniscale senza trovare differenze — un dato muto, non un'equivalenza dimostrata, perché il campione è troppo piccolo. Il raccoglitore notturno non è passato anche stanotte, dodicesimo giorno consecutivo: richiami, congressi, società e destino dei verdetti restano non verificati per oggi; le ritrattazioni sono state comunque ricontrollate a mano su tutti i 235 PMID dello storico, senza nulla di nuovo.";
var BRIEF_DIALOGO=[{"chi":"A","t":"Oggi la scheda di apertura è un dato di registro, non uno studio clinico dedicato — ma con oltre 120.000 protesi di ginocchio dietro."},{"chi":"B","t":"Il registro svizzero? Che cosa mostra esattamente?"},{"chi":"A","t":"Che chi ha già operato in passato lo stesso ginocchio — un'osteotomia, il crociato anteriore, un'infezione — rischia di più una revisione per infezione dopo la protesi totale."},{"chi":"B","t":"Quindi per te che fai sia LCA sia osteotomie sia protesi, è un dato che si chiude il cerchio."},{"chi":"A","t":"Esatto. E il rischio non è uguale per tutti gli interventi precedenti: più alto dopo una chirurgia per infezione o un'osteotomia, più contenuto dopo il crociato anteriore, e sale ancora oltre due interventi."},{"chi":"B","t":"È un motivo per essere più prudenti con quei pazienti?"},{"chi":"A","t":"Più che altro per dirlo esplicitamente nel colloquio preoperatorio: la storia chirurgica del ginocchio è un fattore di rischio quantificabile, non solo un dettaglio anagrafico."},{"chi":"B","t":"E le altre schede?"},{"chi":"A","t":"Una meta-analisi di 30 studi conferma che l'allenamento neuromuscolare previene gli infortuni al ginocchio nello sport, a ogni età — meglio se il programma è completo e standardizzato."},{"chi":"B","t":"Poi ci sono tre lavori sulla tensione del rientro allo sport, giusto?"},{"chi":"A","t":"Sì. Uno studio turco mostra che il ginocchio ricostruito resta percepito come diverso da quello sano anche dopo anni, e che conta più la fiducia psicologica del paziente che la stabilità misurata dal medico."},{"chi":"B","t":"E il secondo?"},{"chi":"A","t":"Uno studio biomeccanico cinese: durante un atterraggio impegnativo, nel ginocchio operato manca uno schema muscolare specifico che stabilizza lateralmente il ginocchio — anche quando la forza è tornata quasi normale."},{"chi":"B","t":"E l'ultimo, quello sul menisco?"},{"chi":"A","t":"Un esperimento di laboratorio su tessuto animale: confronta due tecniche di sutura della radice meniscale, nessuna vince chiaramente. Ma il campione è troppo piccolo per dire che sono davvero equivalenti — resta un dato muto. Il raccoglitore notturno resta fermo per il dodicesimo giorno di fila: richiami e congressi non verificati, ma le ritrattazioni le ho ricontrollate a mano su tutto lo storico."}];
